    "ratingRaw": "Mostly Difficult Day",
    "aggression": true,
    "notes": "Signs / reasons - very low appetite; barely eating; had very small breakfast, no snacks, told us he only had some grapes for lunch; took baby bear to school today after a LONG time; sad about Elysse (girl he met in camp) not calling? Said he was scared but didn't elaborate, said he didn't belong here and wants to leavehad a good morning; Ms Fran called at dismissal saying he is refusing to go to after care; we need to come pick him up; he was in front office reading; we got to school within 5 mins; the new principal met us at the front door and we talked for a while; her filling us in on him having a hard time with after care transition and going to the front office to Michelle who is a familiar face; we explained transitions have always been a challenge; she told us she would bring him out; after a while came back and told us he is refusing to leave; we found him sitting on the floor behind Michelle's desk flipping through the year book; wouldn't leave with us; at one point ran into the nurse's office; started yelling and resisting being carried out; eventually dad had him restrained and managed to get him out of the building; he kept yelling he wants to go to after care; but then he wouldn't get in the car; as we were trying to coax him we were told by the case manager that the principal has called the police; soon 2 cop cars arrived with lights on; by this time we were on the steps of the Media Center door; we were holding on to him so he wouldn't run and was thrashing around some not wanting to be restrained; the police took our info; talked to him and soon he was calm; but still refused to get in the car; finally dad convinced him to get in the car by offering his phone; while all this was happening principal, new councelor and new case manager were all standing around like \"watching the entertainment\" from the parking lot; police gave us a case numberonce home he stayed on the phone for a while till dad took it back; didn't want to get in the pool; went to his room still angry and packed his clothes saying he wanted to leave and hates it here; eventually dad got him to read and calm him down; rest of the evening was fine; he watched some TV; had pizza for dinner; played in the backyardspoke to Dr. Barness; he said to re-start Risperdone; have appointment on Tuesday",
