    "ratingRaw": "Almost good day",
    "aggression": true,
    "notes": "had a good morning and drop off; was good at pickup although complaining about his knee which he hurt in Ninja and wanting an x-ray; did his math homework once home (although incorrectly); he agreed to look at them once we got home from the doctor; was good on the drive over but started whining and being cranky once he saw dad's car pull in (we were waiting in my car for dad to be done with his work call); walked into the doctor's office with an attitude and complaining about being hungry; had dad go the mall to grab something; mentioned to Dr. Barness that his current issues are mainly meltdowns still happening once or twice / week on average although mild to moderate; and focus and attention in school; since he is already on 3 meds agreed with doctor that adding more meds isn't the right approach; we will try to wean him off Risperdal starting this Friday and see how that goes firstwent out for sushi at Tokyo Sushi in Chatham and he was good there; once home he did fix his homework with dad's help; wanted to watch TV even though it was quite late (7.30pm) but we agreed to 10 mins; was good about going to bed but started to whine about a story even though he was clearly very tired; fell asleep shortly afterFrom school today:Hi. As we mentioned xavier is doing much better with transitions. When he is off task or needs redirection he doesn't argue with the adult and can easily make that transition. In terms of attention/ focus we are still seeing a lot of distractability. He needs frequent reminders to get on task and stay on task. He has difficulty working independently and in groups as he often gets easily distracted by objects in the room or his own thoughts . He has difficulty multitasking . If he sits with the teacher and she monitors him and redirects he can mostly complete a task. But it takes a while for him to do that task. He likes to talk to the teacher and get off topic. He gets along with the children and seems so happy to be here.",
