    "ratingRaw": "",
    "aggression": true,
    "notes": "travel to Plovdiv (~2 hrs with traffic). Had a long wait at the car rental. He did fairly well (although did take food from strangers). Also did well on the drive. Got to the hotel. Checked in and got to room. With no trigger warning started growling, hissing, pouncing and scratching. Went on for a while till we managed to get him out of the room and into the playground next door. Took ~1.5 hours to calm down. Using calming voices worked. Ended up having dinner in the hotel. Was very hyper throughout dinner. Took a bath once back in room. Took a while to fall asleep ~9.45pm. Took most of our pillows. But then woke up around 4am. We tried many different things - cuddling together, different podcasts. He was almost having a panic attack, hyperventilating, feeling very antsy. Very physical reaction (but not aggressive) that we haven\u2019t seen before. Didn\u2019t yell though. He has a whole secret language he calls Z Spanish that he keeps using with his stuffies. Lots of baby talk. Finally around 6.30 we tried headphones with his favorite audio book and he finally fell asleep. We did too, absolutely exhausted not having slept at all.",
