    "notes": "got up up a bit early for the first test session with Dr Koffman; was fine getting dressed and getting in the car; when we got there he was shy and didn't want to start the test; took about 15 mins of coaxing before he settled down; during break we went out to get drinks and he had a HC, macaroon and blueberry muffin; afterwards went to a bookstore that he refused to leave and insisted on buying 2 books; we refused and he very grudgingly settled on one; did fine at lunch and at the voting place (for early voting); it was raining very hard; so we got back in the car and headed home to change into dry clothes; he initially insisted (with an attitude) he did not want to go home but then seemed fine with it; once we got home he was copping major attitude and wasn't calm at all; was irritable; ignoring us while reading;  we wavered on whether to take him to Creatiff like we had promised fearing a meltdown was imminent; we ended up going anyway once he was a bit calmer but it turned out to be a big mistake; he insisted on wanting the biggest projects which were very expensive; wasn't happy with the birdhouse he selected; kept whining for more and was spiralling towards a meltdown; so Tom carried him out of there while he was fighting back hard, hitting and kicking and at one point broke loose and ran hard; kept hitting the back of the seat and Tom while he was driving on the drive back home; verbally abusive calling us \"idiots\". \"losers\" and much more; once we got back home around 4.30pm he hit and kicked us several times; he was using his cat sounds and moves again; took all evening to calm down; he commented on whether he might not be allowed to go trick or treating tomorrow; he also told Tom at bedtime that he was nervous about going to the doctor; eventually fell asleep little after 8pm [Meds: melatonin]",
