    "rating": 5,
    "ratingRaw": "",
    "aggression": false,
    "notes": "From dad:Xavier had a great morning although drop off was a bit challenging; no problem going in, but the older kids had a movie playing and something on the screen scared Xavier and he came running to me. I talked to him and just told him they should not watch it and do something else; from what I heard from Ashley he did go in color instead of watching TV. Text from Ashley:Hi this is Ashley Sophia from the Jen site gap program in Livingston I'm reaching out just to let you know that Xavier is having a very difficult time we are requesting that you come pick him up at this time unfortunately he refuses to get out from under the table which does pose a safety risk and he's refusing any of the skills or support so I did also try calling mom but unfortunately she's not accepting phone calls at this time so if you can please call me back 9739941011 my extension is 5142 thank you\u2026\u201d The story I heard from Rachel it sounds like some kids were teasing him in the session. Nobody seemed to have heard that but it upset Xavier. He crawled under the table and was screaming. They decided to leave him alone for 10 minutes after he wouldn\u2019t use any of his techniques he did calm himself down. They were very proud of him. They did call me to ask me to come pick him up but then shortly after they called me back and told me I did not need to pick him up. He calmed down. The rest of the day was pretty smooth. Receptionist was giving out candy at the end of the day. She was questioning whether he had been good. Xavier apologized to her for being in the morning and got his candy. They agreed to have a better day tomorrow when we got home. I did try to assure Xavier, he could talk to me and he just said he didn\u2019t want to talk about it, but he did have a great afternoon. He did later question that they told on him and they never told him they were going to do that I replied back saying I heard the conversation when I was picking you up and left it at that had a really good afternoon at home watching Molly from Denali for half an hour while I had a phone call and then we went to dinner really enjoyed calling. Mommy had a good dinner at Shake shack had a bath when we got home read his stories and was asleep within minutes. I did try to bring up the conversation again during that time he didn\u2019t want to talk about it start getting upset so I dropped it overall a good day on my side disappoint about what happened at school. [Meds: melatoninmom on work trip]",
