    "notes": "woke up a bit late around 8am in a good mood; stayed in bed reading for a whole; was tired but came downstairs for breakfast and meds; then went back up to read more in his room; then started to get upset when it was time to get dressed for his 10am appointment with Melissa; was getting angry but no physical aggression; he did punch the cushion and cardboard boxes to get some of the anger out; eventually made it to the appointment in his PJs but still saying he was angry; at the appointment he was not very communicative or engaging (but not angry or rude) and didn't want to do any of the exercises or strategies she wanted him to learn; was climbing all over daddy; after the appointment he went home with dad while I had errands to run; once home he did some more reading on the Kindle; had some snacks and then lunch around 12.30pm; wanted to go to Skyzone; was calm at that point and good at first but while at Skyzone had an altercation with 2 other boys who were being mean and bullying him; he ended up having a meltdown yelling angrily at them to stop it; manager came over to help diffuse the situation; had to be carried out to the car; was still angry, crying and hitting dad; eventually calmed down in the car; dad went back in to get the jackets; once home he was calm; we talked to him about how we support and love him; had a good rest of the day; took a bath; enjoyed NYE dinner at Brick and Dough; talked about wanting to stay up till midnight but fell asleep by 8pm [Meds: melatonin]",
